SET ROLE talus_fn;
CREATE TABLE app.pricing_revision(tenant_id uuid NOT NULL,pricing_revision_id uuid NOT NULL,booking_id uuid NOT NULL,revision_no integer NOT NULL CHECK(revision_no>0),reason text NOT NULL,pricing_policy_version_id uuid,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,pricing_revision_id),UNIQUE(tenant_id,booking_id,revision_no),FOREIGN KEY(tenant_id,booking_id) REFERENCES app.booking(tenant_id,booking_id));
CREATE TABLE app.price_line(tenant_id uuid NOT NULL,pricing_revision_id uuid NOT NULL,line_no integer NOT NULL CHECK(line_no>0),line_type text NOT NULL CHECK(line_type IN('rental_subtotal','multi_day_discount','addon','promo_discount','tax','mandatory_fee','platform_fee','deposit','total')),amount_cents bigint NOT NULL,rate_bp integer CHECK(rate_bp BETWEEN 0 AND 10000),PRIMARY KEY(tenant_id,pricing_revision_id,line_no),FOREIGN KEY(tenant_id,pricing_revision_id) REFERENCES app.pricing_revision(tenant_id,pricing_revision_id));
CREATE TABLE app.promo_code(tenant_id uuid NOT NULL,promo_code_id uuid NOT NULL,code text NOT NULL,discount_cents bigint,discount_bp integer,maximum_redemptions integer,redemption_count integer NOT NULL DEFAULT 0 CHECK(redemption_count>=0),active boolean NOT NULL DEFAULT true,PRIMARY KEY(tenant_id,promo_code_id),CHECK((discount_cents IS NOT NULL)<>(discount_bp IS NOT NULL)),CHECK(discount_cents IS NULL OR discount_cents>=0),CHECK(discount_bp IS NULL OR discount_bp BETWEEN 0 AND 10000),CHECK(maximum_redemptions IS NULL OR maximum_redemptions>0));
CREATE UNIQUE INDEX promo_code_tenant_upper_code_uq ON app.promo_code(tenant_id,upper(code));
CREATE TABLE app.promo_redemption(tenant_id uuid NOT NULL,promo_redemption_id uuid NOT NULL,promo_code_id uuid NOT NULL,booking_id uuid NOT NULL,pricing_revision_id uuid,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,promo_redemption_id),UNIQUE(tenant_id,promo_code_id,booking_id),FOREIGN KEY(tenant_id,promo_code_id) REFERENCES app.promo_code(tenant_id,promo_code_id),FOREIGN KEY(tenant_id,booking_id) REFERENCES app.booking(tenant_id,booking_id));
CREATE OR REPLACE FUNCTION app.calculate_quote(p_rate uuid,pickup timestamptz,dropoff timestamptz,tz text,p_code text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE t uuid:=app.current_context_tenant_id();r app.product_rate%ROWTYPE;d integer;s bigint;x bigint:=0;p app.promo_code%ROWTYPE; BEGIN PERFORM app.require_context();SELECT * INTO r FROM app.product_rate WHERE tenant_id=t AND product_rate_id=p_rate;IF NOT FOUND THEN RAISE EXCEPTION 'RESOURCE_NOT_FOUND' USING ERRCODE='P0001';END IF;d:=GREATEST((dropoff AT TIME ZONE tz)::date-(pickup AT TIME ZONE tz)::date,1);s:=r.daily_rate_cents*d;IF p_code IS NOT NULL THEN SELECT * INTO p FROM app.promo_code WHERE tenant_id=t AND upper(code)=upper(p_code) AND active;IF NOT FOUND THEN RAISE EXCEPTION 'PROMO_NOT_FOUND' USING ERRCODE='P0001';END IF;x:=LEAST(s,COALESCE(p.discount_cents,(s*p.discount_bp)/10000));END IF;RETURN jsonb_build_object('day_count',d,'rental_subtotal_cents',s,'promo_discount_cents',x,'total_cents',s-x);END; $$;
CREATE OR REPLACE FUNCTION app.create_price_snapshot(p_id uuid,p_booking uuid,p_rate uuid,pickup timestamptz,dropoff timestamptz,tz text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE t uuid:=app.current_context_tenant_id();q jsonb;BEGIN PERFORM app.require_staff_role('staff');q:=app.calculate_quote(p_rate,pickup,dropoff,tz);INSERT INTO app.pricing_revision VALUES(t,p_id,p_booking,1,'confirmed',NULL,clock_timestamp());INSERT INTO app.price_line VALUES(t,p_id,1,'rental_subtotal',(q->>'rental_subtotal_cents')::bigint,NULL),(t,p_id,2,'total',(q->>'total_cents')::bigint,NULL);PERFORM app.append_audit('pricing.snapshot_created','pricing_revision',p_id);RETURN p_id;END; $$;
CREATE OR REPLACE FUNCTION app.append_price_revision(p_id uuid,p_booking uuid,p_reason text,p_total bigint) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE t uuid:=app.current_context_tenant_id();n integer;BEGIN PERFORM app.require_staff_role('staff');SELECT COALESCE(max(revision_no),0)+1 INTO n FROM app.pricing_revision WHERE tenant_id=t AND booking_id=p_booking;INSERT INTO app.pricing_revision VALUES(t,p_id,p_booking,n,p_reason,NULL,clock_timestamp());INSERT INTO app.price_line VALUES(t,p_id,1,'total',p_total,NULL);PERFORM app.append_audit('pricing.revision_appended','pricing_revision',p_id);RETURN p_id;END; $$;
CREATE OR REPLACE FUNCTION app.redeem_promo_code(p_id uuid,p_code text,p_booking uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=app,pg_catalog AS $$ DECLARE t uuid:=app.current_context_tenant_id();p app.promo_code%ROWTYPE;BEGIN PERFORM app.require_context();SELECT * INTO p FROM app.promo_code WHERE tenant_id=t AND upper(code)=upper(p_code) AND active FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'PROMO_NOT_FOUND' USING ERRCODE='P0001';END IF;IF p.maximum_redemptions IS NOT NULL AND p.redemption_count>=p.maximum_redemptions THEN RAISE EXCEPTION 'PROMO_REDEMPTION_LIMIT_REACHED' USING ERRCODE='P0001';END IF;INSERT INTO app.promo_redemption(tenant_id,promo_redemption_id,promo_code_id,booking_id) VALUES(t,p_id,p.promo_code_id,p_booking);UPDATE app.promo_code SET redemption_count=redemption_count+1 WHERE tenant_id=t AND promo_code_id=p.promo_code_id;PERFORM app.append_audit('promo.redeemed','promo_code',p.promo_code_id);RETURN p_id;END; $$;
DO $$ DECLARE x text;BEGIN FOREACH x IN ARRAY ARRAY['pricing_revision','price_line','promo_code','promo_redemption'] LOOP EXECUTE format('ALTER TABLE app.%I ENABLE ROW LEVEL SECURITY;ALTER TABLE app.%I FORCE ROW LEVEL SECURITY;CREATE POLICY tenant_context_policy ON app.%I USING(tenant_id=app.current_context_tenant_id() AND app.context_is_valid()) WITH CHECK(tenant_id=app.current_context_tenant_id() AND app.context_is_valid())',x,x,x);END LOOP;END; $$;
REVOKE UPDATE,DELETE ON app.pricing_revision,app.price_line FROM PUBLIC,talus_fn,talus_api,talus_customer,talus_staff,talus_device;
REVOKE ALL ON ALL TABLES IN SCHEMA app FROM talus_api,talus_customer,talus_staff,talus_device;
RESET ROLE;
